            stack = [node]
            while stack:
                current = stack.pop()
                for neighbor in graph[current]:
                    if neighbor not in orbit:
                        orbit.add(neighbor)
                        stack.append(neighbor)
            orbits.add(tuple(sorted(orbit)))
        return len(orbits)

